import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { PermissionGuard } from '../../../core/guard/permission/permission.guard';

const routes: Routes = [
  { path: '', redirectTo: 'feed', pathMatch: 'full' },
  // { path: 'feed/:id', loadComponent: () => import('../../components/feed-display/feed-display.component').then(m => m.FeedDisplayComponent) }
  {
    path: 'feed/:id',
    loadComponent: () => import('../../components/feeds/realtime/realtime-shell.component').then(m => m.RealtimeShellComponent),
    data: { permission: 'RT' },
    canActivate: [PermissionGuard]
  },
  {
    path: 'dashboard/:id',
    loadComponent: () => import('../../components/dashboard/dashboard.component').then(m => m.DashboardComponent),
    data: { permission: 'RT' },
    canActivate: [PermissionGuard]
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})

export class rtRoutingModule { }
